"""C3: methods facts, pulled from the code and the harmonized tables (not from memory).
Writes results/methods_facts.md and results/methods_facts_per_subject.csv.
Condition-dependence check: bad channels and ICA are fit/applied per SUBJECT across runs (union of bad channels, one shared ICA), so counts
cannot differ between conditions by construction (verified from the tables). The preprocessing step that CAN differ by condition is bad-segment
epoch rejection, so epochs retained (n_epochs / floor(run duration / 4 s)) are compared with a paired Wilcoxon test.
"""
import inspect, re
from pathlib import Path
import numpy as np, pandas as pd
from scipy import stats
import braboszcz_feature_extraction as b
import reextract_harmonized as rh
from combined_supplementary import bootstrap_ci

H = Path('results/harmonized'); R = Path('results')
def tab(name): return pd.read_csv(H/name, usecols=lambda c: not any(c.endswith(x) for x in ('_delta', '_theta', '_alpha', '_beta', '_gamma1', '_gamma2', '_IAF')) and 'ratio' not in c and not c.startswith('asym'))
T = {'braboszcz': tab('braboszcz_all_subjects_features.csv'), 'braboszcz_ctr': pd.read_csv(H/'braboszcz_ctr_features.csv', usecols=['dataset', 'subject', 'condition', 'epoch_idx', 'bad_channels', 'ica_excluded', 'group', 'age']),
     'brandmeyer': tab('brandmeyer_all_subjects_features.csv'), 'sky': tab('sky_all_subjects_features.csv')}
def n_items(x): return 0 if pd.isna(x) or str(x) == '' else len(str(x).split(','))
rows = []
for name, d in T.items():
    for s, g in d.groupby('subject'):
        r = dict(dataset=name, subject=s, bad_channels=g.bad_channels.iloc[0] if pd.notna(g.bad_channels.iloc[0]) else '', n_bad_channels=n_items(g.bad_channels.iloc[0]),
                 ica_excluded=g.ica_excluded.iloc[0] if pd.notna(g.ica_excluded.iloc[0]) else '', n_ics_removed=n_items(g.ica_excluded.iloc[0]),
                 constant_within_subject=bool(g.bad_channels.fillna('').nunique() == 1 and g.ica_excluded.fillna('').nunique() == 1))
        r.update({f'n_epochs_{c}': int(n) for c, n in g.groupby('condition').size().items()}); rows.append(r)
P = pd.DataFrame(rows); P.to_csv(R/'methods_facts_per_subject.csv', index=False)
src = lambda f: inspect.getsource(f).strip()
ica_lines = [l.strip() for l in inspect.getsource(rh.prep_paired).splitlines() if re.search(r'ICA\(|\.fit\(cat_f|find_bads|filter\(l_freq|set_eeg_reference|resample|decim', l)]
cohort = pd.read_csv(H/'cohort_by_analysis.csv')
ro = pd.read_csv(H/'braboszcz_run_order.csv')
# retained epochs per condition
dur = {'MED': 'med2_dur_s', 'IMW2': 'think2_dur_s', 'IMW1': 'think1_dur_s'}
B = pd.concat([T['braboszcz'], T['braboszcz_ctr'][['subject', 'condition']]]).groupby(['subject', 'condition']).size().unstack()
ret = pd.DataFrame({c: B[c]/np.floor(ro.set_index('subject')[dur[c]].reindex(B.index)/4.0) for c in dur}).dropna()
tests = []
for a, c, label in [('MED', 'IMW2', 'MED vs IMW2'), ('IMW1', 'IMW2', 'think1 vs think2')]:
    z = ret[[a, c]].dropna(); dlt = (z[a]-z[c]).to_numpy(); w = stats.wilcoxon(dlt) if np.any(dlt != 0) else None; lo, hi = bootstrap_ci(dlt)
    tests.append(f'| {label} | {len(z)} | {z[a].mean():.3f} | {z[c].mean():.3f} | {dlt.mean():+.3f} [{lo:+.3f}, {hi:+.3f}] | {w.pvalue:.3g} |')
cnt = []
for a, c in [('MED', 'IMW2'), ('IMW1', 'IMW2')]:
    z = B[[a, c]].dropna(); w = stats.wilcoxon((z[a]-z[c]).to_numpy()); cnt.append(f'| {a} vs {c} | {len(z)} | {z[a].mean():.1f} | {z[c].mean():.1f} | {w.pvalue:.3g} |')
const = P.groupby('dataset').constant_within_subject.mean()
md = []; A = md.append
A('# Methods facts (generated by `methods_facts.py` from code and harmonized tables)\n')
A('## Signal processing (code: `reextract_harmonized.py`, `braboszcz_feature_extraction.py`)')
A(f'- Channels: {len(b.COMMON_CHANNELS_14)} common EEG channels: {", ".join(b.COMMON_CHANNELS_14)}.')
A(f'- Line-noise notch: {rh.LINE_NOTCH} Hz (both applied). High-pass: {rh.HP} Hz, 6th-order zero-phase Butterworth IIR. No low-pass beyond resampling to {b.TARGET_SFREQ:g} Hz (Nyquist 128 Hz); the PSD uses {b.PSD_FMIN:g}-{b.PSD_FMAX:g} Hz.')
A('- Reference: average reference over the 14 common channels, after interpolating bad channels (main pipeline). Variant B4-ref64 references over all 64 EEG channels first.')
A(f'- Bad channels: MAD-based robust variance z-score > 6.0 per run (`detect_bad_channels_by_variance(raw, z_thresh=6.0)`); the UNION across a subject\'s runs is interpolated (spherical spline, MNE) when channel positions exist.')
A(f'- Bad segments (Braboszcz/Brandmeyer; skipped for SKY because the detector flagged >=95% of every EDF): window {b.REJCONT_SEG_LEN:g} s, step {b.REJCONT_SEG_STEP:g} s, low band {b.REJCONT_LOW_BAND} Hz > {b.REJCONT_LOW_THRESH_DB:g} dB or high band {b.REJCONT_HIGH_BAND} Hz > {b.REJCONT_HIGH_THRESH_DB:g} dB, >= {b.REJCONT_MIN_CONSEC} consecutive windows.')
A('- ICA (lines extracted from `prep_paired`):\n```\n' + '\n'.join(ica_lines) + '\n```')
A(f'- Epochs: non-overlapping {b.EPOCH_LEN_SEC:g} s fixed-length epochs, overlap {b.EPOCH_OVERLAP_SEC:g} s; epochs overlapping bad-segment annotations are dropped (`reject_by_annotation=True`). Brandmeyer: two contiguous 4 s epochs per probe, starting 8.05 s and 4.05 s before the probe onset.')
A('\n## Features (code: `braboszcz_feature_extraction.py`)')
A(f'- PSD: multitaper (MNE default), {b.PSD_FMIN:g}-{b.PSD_FMAX:g} Hz. Band power: trapezoidal integral of the band divided by total {b.PSD_FMIN:g}-{b.PSD_FMAX:g} Hz power (RELATIVE power); bands [lo, hi) Hz: {dict(b.CANONICAL_BANDS)}.')
A(f'- Asymmetry pairs (left, right): {b.ASYMMETRY_PAIRS}. Formula: asym = ln(right band power + 1e-20) - ln(left band power + 1e-20), per band (not log-transformed again downstream).')
A('```\n' + src(b.asymmetry_index) + '\n```')
A(f'- Cross-band ratios per channel: {b.RATIO_DEFS} (sum of numerator bands / (sum of denominator bands + 1e-20)); log-transformed downstream.')
A('```\n' + src(b.cross_band_ratios) + '\n```')
A(f'- IAF: per epoch and channel, frequency of the maximum PSD value within {b.IAF_SEARCH_BAND} Hz (argmax; not centre-of-gravity; not log-transformed).')
A('```\n' + src(b.individual_alpha_frequency) + '\n```')
A('- Downstream transform (`combined_analysis.load_data`): natural log of every feature except asymmetry and IAF, values clipped below at 1e-12; 196 common features (84 band, 56 ratio, 42 asymmetry, 14 IAF).')
A('\n## Final N per dataset')
A('| Dataset / analysis | N | Note |\n|---|---|---|')
for _, r in cohort.iterrows(): A(f'| {r.dataset}: {r.analysis} | {r.N} | loaded {r.n_loaded} |')
A(f'| braboszcz CTR (trait analysis) | {T["braboszcz_ctr"].subject.nunique()} | harmonized extraction, no failures |')
A(f'| harmonized tables | braboszcz {T["braboszcz"].subject.nunique()}, brandmeyer {T["brandmeyer"].subject.nunique()}, sky {T["sky"].subject.nunique()} | |')
A('\n## Per-subject preprocessing counts (full table: `results/methods_facts_per_subject.csv`)')
s = P.groupby('dataset').agg(n_subjects=('subject', 'size'), bad_ch_mean=('n_bad_channels', 'mean'), bad_ch_max=('n_bad_channels', 'max'), subjects_with_bad_ch=('n_bad_channels', lambda x: int((x > 0).sum())),
                             ics_removed_mean=('n_ics_removed', 'mean'), ics_removed_min=('n_ics_removed', 'min'), ics_removed_max=('n_ics_removed', 'max'))
A('```\n' + s.round(2).to_string() + '\n```')
ec = P.filter(regex='^n_epochs_|^dataset$').groupby('dataset').agg(['mean', 'min', 'max']).round(1); A('\nEpochs per subject by condition (mean, min, max):\n```\n' + ec.to_string() + '\n```')
A('\n## Do interpolated channels / removed ICs differ between conditions?')
A(f'- Fraction of subjects whose bad-channel list and excluded-IC list are identical across all their conditions: {const.round(3).to_dict()}. Bad channels are interpolated as the union across runs and one ICA is fit on the concatenated runs of a subject, so these counts are identical across conditions by construction. A paired test is therefore degenerate (all differences are 0); no test is reported for them.')
A('- What can differ by condition is bad-segment epoch rejection. Epochs retained = n_epochs / floor(run duration / 4 s), Braboszcz (experienced + CTR subjects with durations in `braboszcz_run_order.csv`), paired Wilcoxon signed-rank:')
A('\n| Contrast | N | mean A | mean B | mean diff A-B [95% CI] | p |\n|---|---|---|---|---|---|'); [A(t) for t in tests]
A('\nRaw epoch counts per subject (paired Wilcoxon):\n\n| Contrast | N | mean A | mean B | p |\n|---|---|---|---|---|'); [A(t) for t in cnt]
A('\n## Caveats found while extracting these facts')
sk = P[P.dataset == 'sky']; A(f'- SKY: median {sk.n_ics_removed.median():.0f} ICs removed per subject (range {sk.n_ics_removed.min()}-{sk.n_ics_removed.max()}); with 14 channels at most ~13 components exist, so many SKY subjects have most components removed. The total component count is not stored, so the removed fraction cannot be computed from the tables.')
A('- CTR subjects: the "MED" run (med2) is breath counting, not a tradition-specific practice (dataset README).')
(R/'methods_facts.md').write_text('\n'.join(md)); print('\n'.join(md[-30:]))
